const prev = $('Unir consulta + fragmentos').all();
return $input.all().map((it, i) => {
  const b = prev[i].json;
  return { json: {
    caso_id: b.caso_id,
    tema: b.tema,
    consulta: b.consulta,
    contexto: b.contexto,
    respuesta_esperada: b.respuesta_esperada,
    arquitectura: 'A',
    arquitectura_nombre: 'A - Agente CON RAG (recuperacion del manual, Modulo 5)',
    respuesta: String(it.json.text || it.json.output || ''),
    fragmentos_recuperados: b.fragmentos,
    intento: 1
  }};
});

const banco = $('Banco de 5 preguntas (ground truth)').all();
return $input.all().map((it, i) => {
  const b = banco[i].json;
  return { json: {
    caso_id: b.caso_id,
    tema: b.tema,
    consulta: b.consulta,
    contexto: b.contexto,
    respuesta_esperada: b.respuesta_esperada,
    arquitectura: 'B',
    arquitectura_nombre: 'B - Agente SIN RAG (memoria parametrica)',
    respuesta: String(it.json.text || it.json.output || ''),
    fuentes_declaradas: '',
    requiere_humano_agente: false,
    intento: 1
  }};
});

// ---- Parametros de coste (editables). Gemini 2.5 Flash, prompts <= 200k tokens ----
const PRECIO_IN  = 0.75 / 1000000;   // USD por token de entrada
const PRECIO_OUT = 3.00 / 1000000;   // USD por token de salida
const CHARS_POR_TOKEN = 4;           // estimador estandar
const SYS_AGENTE_A = 900;            // chars del system prompt del agente con RAG
const SYS_AGENTE_B = 620;            // chars del system prompt del agente sin RAG
const RAG_CHARS    = 1800;           // fragmentos recuperados por el RAG (Top-K 4)
const SYS_JUEZ     = 3100;           // chars del system prompt del Juez

const tok = (chars) => Math.round(chars / CHARS_POR_TOKEN);
const corridas = $('Unificar las 10 corridas').all();

return $input.all().map((it, i) => {
  const c = corridas[i].json;
  const v = it.json;

  // --- coste del agente ---
  const agenteIn  = (c.arquitectura === 'A')
      ? SYS_AGENTE_A + c.consulta.length + RAG_CHARS
      : SYS_AGENTE_B + c.consulta.length;
  // nota: RAG_CHARS es el promedio de los fragmentos recuperados (Top-K 4, Minimum Score 0.65)
  const agenteOut = (c.respuesta || '').length;

  // --- coste del Juez (1ra pasada, + 2da si hubo self-healing) ---
  let juezIn  = SYS_JUEZ + c.consulta.length + (c.contexto || '').length + (c.respuesta || '').length;
  let juezOut = 260; // salida JSON estructurada, tamano estable
  let reintentoIn = 0, reintentoOut = 0;
  if (v.autocorregido === true) {
    reintentoIn  = 700 + c.consulta.length + (c.contexto || '').length + (c.respuesta || '').length;
    reintentoOut = (v.respuesta_final || '').length;
    juezIn  += SYS_JUEZ + c.consulta.length + (c.contexto || '').length + (v.respuesta_final || '').length;
    juezOut += 260;
  }

  const tokensIn  = tok(agenteIn) + tok(juezIn) + tok(reintentoIn);
  const tokensOut = tok(agenteOut) + tok(reintentoOut) + juezOut;
  const coste = tokensIn * PRECIO_IN + tokensOut * PRECIO_OUT;

  return { json: {
    corrida: i + 1,
    caso_id: c.caso_id,
    tema: c.tema,
    arquitectura: c.arquitectura,
    exactitud_factual: v.exactitud_final,
    veredicto: v.ruta,
    categoria_error: v.categoria_error,
    cita_verificada: v.cita_verificada === true,
    autocorregido: v.autocorregido === true,
    requirio_humano: v.requirio_humano === true,
    tokens_in: tokensIn,
    tokens_out: tokensOut,
    coste_usd: Number(coste.toFixed(6)),
    critica_del_juez: v.critica,
    respuesta_del_agente: c.respuesta
  }};
});

const filas = $input.all().map(i => i.json);
const VOLUMEN = 1000;

const resumen = (letra) => {
  const f = filas.filter(x => x.arquitectura === letra);
  const n = f.length || 1;
  const avg = (sel) => f.reduce((a, x) => a + (Number(sel(x)) || 0), 0) / n;
  const pct = (sel) => Math.round(f.filter(sel).length / n * 100);
  const errores = {};
  f.forEach(x => { const k = x.categoria_error || 'SIN_ERROR';
                   if (k !== 'SIN_ERROR') errores[k] = (errores[k] || 0) + 1; });
  const top = Object.entries(errores).sort((a, b) => b[1] - a[1])
                .map(([k, v]) => k + ' (' + v + ')').join(' | ') || 'sin errores';
  const costeCorrida = avg(x => x.coste_usd);
  return {
    arquitectura: letra,
    corridas: f.length,
    precision_media: Number(avg(x => x.exactitud_factual).toFixed(2)),
    pct_aceptado: pct(x => x.veredicto === 'ACEPTADO'),
    pct_corregir: pct(x => x.veredicto === 'CORREGIR'),
    pct_rechazado: pct(x => x.veredicto === 'RECHAZADO'),
    pct_autonomia: pct(x => x.requirio_humano !== true),
    pct_cita_verificada: pct(x => x.cita_verificada === true),
    errores_frecuentes: top,
    tokens_por_corrida: Math.round(avg(x => x.tokens_in + x.tokens_out)),
    coste_por_corrida_usd: Number(costeCorrida.toFixed(6)),
    coste_1000_ejecuciones_usd: Number((costeCorrida * VOLUMEN).toFixed(2))
  };
};

const A = resumen('A'), B = resumen('B');
const deltaPrecision = Number((A.precision_media - B.precision_media).toFixed(2));
const deltaCoste = Number((A.coste_1000_ejecuciones_usd - B.coste_1000_ejecuciones_usd).toFixed(2));
const COSTE_HUMANO_CASO = 3.50; // USD: 7 min de un agente L1 a USD 30/h

const humanosA = Math.round((100 - A.pct_autonomia) / 100 * VOLUMEN);
const humanosB = Math.round((100 - B.pct_autonomia) / 100 * VOLUMEN);
const totalA = A.coste_1000_ejecuciones_usd + humanosA * COSTE_HUMANO_CASO;
const totalB = B.coste_1000_ejecuciones_usd + humanosB * COSTE_HUMANO_CASO;

return [{ json: {
  A, B,
  delta_precision: deltaPrecision,
  delta_coste_llm_1000: deltaCoste,
  coste_total_1000_A_usd: Number(totalA.toFixed(2)),
  coste_total_1000_B_usd: Number(totalB.toFixed(2)),
  ahorro_total_1000_usd: Number((totalB - totalA).toFixed(2)),
  supuesto_coste_humano_por_caso_usd: COSTE_HUMANO_CASO,
  casos_a_humano_por_1000: { A: humanosA, B: humanosB }
}}];
